export default function AdminApp() {
  const { user } = useAuth()

  if (!user?.is_system_admin) {
    return <Navigate to="/dashboard" replace />
  }

  return (
    <TooltipProvider>
      <AdminRoutes />
    </TooltipProvider>
  )
}
